import React, { useState, useEffect } from 'react';
import { useSocket } from '../context/SocketContext';
import { useAuth } from '../context/AuthContext';
import API from '../utils/api';
import './SeatMap.css';

const SeatMap = ({ event, onSeatsSelected }) => {
  const socket = useSocket();
  const { user } = useAuth();
  const [selectedSeats, setSelectedSeats] = useState([]);
  const [seatStatuses, setSeatStatuses] = useState({});
  const [lockStatus, setLockStatus] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!event || !event._id || !socket) return;

    // Join event room for real-time updates
    socket.emit('join-event', event._id);

    // Initialize seat statuses from event data
    initializeSeatStatuses();

    // Listen for real-time updates
    socket.on('seat-status-changed', handleSeatStatusChange);
    socket.on('lock-granted', handleLockGranted);
    socket.on('lock-failed', handleLockFailed);
    socket.on('queue-position-updated', handleQueueUpdate);
    socket.on('lock-expired', handleLockExpired);
    socket.on('seats-booked', handleSeatsBooked);

    return () => {
      if (socket) {
        socket.emit('leave-event', event._id);
        socket.off('seat-status-changed');
        socket.off('lock-granted');
        socket.off('lock-failed');
        socket.off('queue-position-updated');
        socket.off('lock-expired');
        socket.off('seats-booked');
      }
    };
  }, [event?._id, socket]);

  const initializeSeatStatuses = () => {
    const statuses = {};
    if (!event.sections) return;

    for (const section of event.sections) {
      for (const row of section.rows) {
        for (const seat of row.seats) {
          const seatKey = `${section.sectionId}::${row.rowId}::${seat.seatId}`;
          statuses[seatKey] = seat.status;
        }
      }
    }
    setSeatStatuses(statuses);
  };

  const handleSeatStatusChange = ({ seats }) => {
    const newStatuses = { ...seatStatuses };
    for (const seat of seats) {
      const seatKey = `${seat.sectionId}::${seat.rowId}::${seat.seatId}`;
      newStatuses[seatKey] = seat.status;
    }
    setSeatStatuses(newStatuses);
  };

  const handleLockGranted = (data) => {
    setLockStatus({
      status: 'granted',
      expiresAt: new Date(data.expiresAt),
      totalPrice: data.totalPrice
    });

    if (onSeatsSelected) {
      onSeatsSelected(data.seats, data.totalPrice);
    }
  };

  const handleLockFailed = (data) => {
    alert(data.message || 'Failed to lock seats. Some seats may no longer be available.');
    setLockStatus(null);
    setSelectedSeats([]);
    // Refresh seat map
    initializeSeatStatuses();
  };

  const handleQueueUpdate = (data) => {
    setLockStatus({
      status: 'queued',
      position: data.position,
      estimatedWait: data.estimatedWait
    });
  };

  const handleLockExpired = () => {
    alert('Your seat lock has expired. Please select seats again.');
    setLockStatus(null);
    setSelectedSeats([]);
    initializeSeatStatuses();
  };

  const handleSeatsBooked = ({ seats }) => {
    // Update display when other users book seats
    handleSeatStatusChange({ seats: seats.map(s => ({ ...s, status: 'booked' })) });
  };

  const handleSeatClick = (sectionId, rowId, seatId, seat, section) => {
    if (lockStatus && lockStatus.status === 'granted') {
      // Lock already granted, can't change selection
      return;
    }

    if (seat.status === 'booked') return;

    const currentStatus = seatStatuses[`${sectionId}::${rowId}::${seatId}`] || seat.status;
    if (currentStatus === 'locked' || currentStatus === 'booked') return;

    const seatKey = `${sectionId}::${rowId}::${seatId}`;

    if (selectedSeats.includes(seatKey)) {
      // Deselect
      setSelectedSeats(selectedSeats.filter(s => s !== seatKey));
    } else {
      // Select
      setSelectedSeats([...selectedSeats, seatKey]);
    }
  };

  const calculateTotalPrice = () => {
    console.log('=== CALCULATING TOTAL PRICE ===');
    console.log('Selected seats:', selectedSeats);
    console.log('Event sections:', event.sections);

    let total = 0;
    for (const seatKey of selectedSeats) {
      const [sectionId] = seatKey.split('::');
      console.log('Looking for sectionId:', sectionId);

      const section = event.sections.find(s => s.sectionId === sectionId);
      console.log('Found section:', section);

      if (section) {
        console.log(`Adding price: ${section.price} (type: ${typeof section.price})`);
        total += section.price;
      } else {
        console.log('⚠️ Section not found for seatKey:', seatKey);
      }
    }
    console.log('Final total:', total);
    console.log('=================================');
    return total;
  };

  const requestLock = async () => {
    if (selectedSeats.length === 0) {
      alert('Please select at least one seat');
      return;
    }

    setLoading(true);

    try {
      const seats = selectedSeats.map(seatKey => {
        const [sectionId, rowId, seatId] = seatKey.split('::');
        return { sectionId, rowId, seatId };
      });

      const res = await API.post('/seat-locks/request', {
        eventId: event._id,
        seats
      });

      if (res.data.granted) {
        // Lock granted immediately
        setLockStatus({
          status: 'granted',
          expiresAt: new Date(res.data.expiresAt),
          totalPrice: res.data.totalPrice
        });
        if (onSeatsSelected) {
          onSeatsSelected(seats, res.data.totalPrice);
        }
      } else {
        // Added to queue
        setLockStatus({
          status: 'queued',
          position: res.data.queuePosition
        });
      }
    } catch (error) {
      alert(error.response?.data?.message || 'Failed to lock seats. Please try again.');
      setLockStatus(null);
    } finally {
      setLoading(false);
    }
  };

  const formatTimeRemaining = (expiresAt) => {
    if (!expiresAt) return '';

    const now = new Date();
    const diff = expiresAt - now;

    if (diff <= 0) return 'Expired';

    const minutes = Math.floor(diff / 60000);
    const seconds = Math.floor((diff % 60000) / 1000);

    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  const CountdownTimer = ({ expiresAt }) => {
    const [timeRemaining, setTimeRemaining] = useState(formatTimeRemaining(expiresAt));

    useEffect(() => {
      const interval = setInterval(() => {
        setTimeRemaining(formatTimeRemaining(expiresAt));
      }, 1000);

      return () => clearInterval(interval);
    }, [expiresAt]);

    return <span className="countdown-timer">{timeRemaining}</span>;
  };

  if (!event.seatMapEnabled || !event.sections || event.sections.length === 0) {
    return (
      <div className="seat-map-not-available">
        <p>Seat map not available for this event</p>
      </div>
    );
  }

  return (
    <div className="seat-map-container">
      {/* Legend */}
      <div className="seat-legend">
        <div className="legend-item">
          <span className="seat-indicator available"></span>
          <span>Available</span>
        </div>
        <div className="legend-item">
          <span className="seat-indicator selected"></span>
          <span>Selected</span>
        </div>
        <div className="legend-item">
          <span className="seat-indicator locked"></span>
          <span>Locked by Others</span>
        </div>
        <div className="legend-item">
          <span className="seat-indicator booked"></span>
          <span>Booked</span>
        </div>
      </div>

      {/* Seat Map Grid */}
      <div className="seat-map-grid">
        {event.sections.map(section => (
          <div
            key={section.sectionId}
            className="seat-section"
            style={{ borderColor: section.color }}
          >
            <h3 className="section-title" style={{ color: section.color }}>
              {section.name} - ${section.price}
            </h3>

            <div className="section-rows">
              {section.rows.map(row => (
                <div key={row.rowId} className="seat-row">
                  <span className="row-label">{row.rowId}</span>

                  <div className="seats">
                    {row.seats.map(seat => {
                      const seatKey = `${section.sectionId}-${row.rowId}-${seat.seatId}`;
                      const isSelected = selectedSeats.includes(seatKey);
                      const currentStatus = seatStatuses[seatKey] || seat.status;

                      return (
                        <button
                          key={seat.seatId}
                          className={`seat seat-${currentStatus} ${isSelected ? 'seat-selected' : ''}`}
                          onClick={() => handleSeatClick(section.sectionId, row.rowId, seat.seatId, seat, section)}
                          disabled={
                            currentStatus === 'booked' ||
                            currentStatus === 'locked' ||
                            (lockStatus && lockStatus.status === 'granted')
                          }
                          title={`${row.rowId}${seat.number} - $${section.price}`}
                        >
                          {seat.number}
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Lock Status & Actions */}
      {lockStatus && (
        <div className="lock-status-container">
          {lockStatus.status === 'queued' && (
            <div className="queue-status">
              <div className="spinner"></div>
              <p>You are in the queue</p>
              <p className="queue-position">Position: #{lockStatus.position}</p>
              <small>Please wait, you'll be notified when seats are locked</small>
            </div>
          )}

          {lockStatus.status === 'granted' && (
            <div className="lock-granted">
              <p className="lock-message">✓ Seats locked!</p>
              <p>Complete booking within: <CountdownTimer expiresAt={lockStatus.expiresAt} /></p>
            </div>
          )}
        </div>
      )}

      {/* Selection Summary */}
      {selectedSeats.length > 0 && !lockStatus && (
        <div className="selection-summary">
          <div className="summary-details">
            <p className="seats-count">{selectedSeats.length} seat(s) selected</p>
            <p className="total-price">${calculateTotalPrice().toFixed(2)}</p>
          </div>
          <button
            className="btn btn-primary continue-btn"
            onClick={requestLock}
            disabled={loading}
          >
            {loading ? 'Processing...' : 'Continue to Booking'}
          </button>
        </div>
      )}
    </div>
  );
};

export default SeatMap;
